HIST_DATA["india-amritsar"] = {"country": "India", "id": "amritsar", "kind": "city", "name_sd": "امرتسر", "name_ur": "امرتسر", "region": "Punjab", "sections_sd": [{"heading": "قديم دور", "text": "روايت موجب سکن جي پھرين گرو، گرو نانڪ، ھن مقام تي عبادت ڪندو ھو. شھر جو نالو امرت سروور يعني آب حيات جي تلاءَ جي نالي تي پيو جنھن جي چوڌاري شھر ٻڌو."}, {"heading": "وچون دور", "text": "1577ع ۾ چوٿين سک گرو رام داس امرت سروور جي کوٽائي ڪرائي ۽ شھر جو بنياد رکيو. روايت موجب ھي زمين مغل بادشاھ اڪبر عطا ڪئي ھئي. پنجين گرو ارجن ديو 1588ع ۾ ھرمندر صاحب جي تعمير شروع ڪئي ۽ 1604ع ۾ آدي گرنٿ ھتي نصب ڪيو. ڇھين گرو ھرگوبند اڪال تخت قائم ڪيو."}, {"heading": "مغل دور", "text": "مغلن سان ٽڪراءَ ۾ ھرمندر صاحب کي ڪيئي ڀيرا نقصان پھتو. ارڙھين صديءَ ۾ سکن ۽ مغل و افغان فوجن وچ ۾ ويڙھن ۾ ھي عمارت تباھ به ٿي. پوءِ سکن ان کي بار بار تعمير ڪيو."}, {"heading": "سک سلطنت", "text": "مھاراجہ رنجيت سنگھ 1809ع ۾ ھرمندر صاحب جي ازسرنو تعمير ڪرائي ۽ 1830ع ۾ ان تي سون جي تھ چاڙھي، جنھن ڪري ھي گولڊن ٽيمپل سڏايو. اڪال تخت سکن جي پنجن تختن مان ھڪ ۽ مذھبي اقتدار جو مرڪز آھي."}, {"heading": "برطانوي دور", "text": "1849ع ۾ انگريزن پنجاب تي قبضو ڪيو ۽ امرتسر برطانوي ھند جو حصو بڻيو. 13 اپريل 1919ع تي جليانوالا باغ ۾ جنرل ڊائر جي حڪم تي اڻھٿيار مظاھرين تي گوليون ھلايون ويون جنھن ۾ سوين ماڻھو ماريا ويا."}, {"heading": "آزاديءَ جي تحريڪ", "text": "جليانوالا باغ جي قتل عام پوري تحريڪ آزاديءَ کي نئين روح بخشي. امرتسر پنجاب ۾ تحريڪ جو اھم مرڪز رھيو."}, {"heading": "1947ع ورهاڱو", "text": "ورھاڱي وقت امرتسر سرحدي شھر ھو؛ ھتي سخت فساد ٿيا ۽ اولھ پنجاب مان سک ۽ ھندو مھاجرن جي وڏي تعداد ھتي آئي. واھگہ سرحد ويجھو ئي واقع آھي."}, {"heading": "جديد دور", "text": "اڄ امرتسر سکن جو مقدس ترين مقام آھي؛ روزانو لکن زائرين اچن ٿا. لنگر ۾ روزانو ھزارين ماڻھن کي مفت کاڌو کارايو وڃي ٿو. 1984ع ۾ ھتي فوجي آپريشن دوران عمارت کي نقصان پھتو، پوءِ ان جي مرمت ڪئي وئي."}], "sections_ur": [{"heading": "قدیم دور", "text": "روایت کے مطابق سکھوں کے پہلے گرو، گرو نانک، اس مقام پر عبادت کیا کرتے تھے۔ شہر کا نام امرت سروور یعنی آب حیات کے تالاب کے نام پر پڑا جس کے گرد شہر بسا۔"}, {"heading": "وسطی دور", "text": "1577 میں چوتھے سکھ گرو رام داس نے امرت سروور کی کھدائی کروائی اور شہر کی بنیاد رکھی۔ روایت کے مطابق یہ زمین مغل بادشاہ اکبر نے عطا کی تھی۔ پانچویں گرو ارجن دیو نے 1588 میں ہرمندر صاحب کی تعمیر شروع کی اور 1604 میں آدی گرنتھ یہاں نصب کیا۔ چھٹے گرو ہرگوبند نے اکال تخت قائم کیا۔"}, {"heading": "مغلیہ دور", "text": "مغلوں کے ساتھ تصادم میں ہرمندر صاحب کو کئی بار نقصان پہنچا۔ اٹھارویں صدی میں سکھوں اور مغل و افغان افواج کے درمیان لڑائیوں میں یہ عمارت تباہ بھی ہوئی۔ بعد میں سکھوں نے اسے بار بار تعمیر کیا۔"}, {"heading": "سکھ سلطنت", "text": "مہاراجہ رنجیت سنگھ نے 1809 میں ہرمندر صاحب کی ازسرنو تعمیر کروائی اور 1830 میں اس پر سونے کی پرت چڑھوائی، جس سے یہ گولڈن ٹیمپل کہلایا۔ اکال تخت سکھوں کے پانچ تختوں میں سے ایک اور مذہبی اقتدار کا مرکز ہے۔"}, {"heading": "برطانوی دور", "text": "1849 میں انگریزوں نے پنجاب پر قبضہ کیا اور امرتسر برطانوی ہند کا حصہ بنا۔ 13 اپریل 1919 کو جلیانوالہ باغ میں جنرل ڈائر کے حکم پر نہتے مظاہرین پر گولیاں چلائی گئیں جس میں سیکڑوں لوگ مارے گئے۔"}, {"heading": "تحریک آزادی", "text": "جلیانوالہ باغ کے قتل عام نے پوری تحریک آزادی کو نئی روح بخشی۔ امرتسر پنجاب میں تحریک کا اہم مرکز رہا۔"}, {"heading": "تقسیم 1947ء", "text": "تقسیم کے وقت امرتسر سرحدی شہر تھا؛ یہاں شدید فسادات ہوئے اور مغربی پنجاب سے سکھ و ہندو مہاجرین کی بڑی تعداد یہاں آئی۔ واہگہ سرحد قریب ہی واقع ہے۔"}, {"heading": "جدید دور", "text": "آج امرتسر سکھوں کا مقدس ترین مقام ہے؛ روزانہ لاکھوں زائرین آتے ہیں۔ لنگر میں روزانہ ہزاروں لوگوں کو مفت کھانا کھلایا جاتا ہے۔ 1984 میں یہاں فوجی آپریشن کے دوران عمارت کو نقصان پہنچا، بعد میں اس کی مرمت کی گئی۔"}], "sources": [{"title": "Golden Temple / Harmandir Sahib – Amritsar Tourism", "url": "https://amritsartourism.org.in/golden-temple-harmandir-sahib-amritsar"}, {"title": "Golden Temple – Wikipedia", "url": "https://en.wikipedia.org/wiki/Golden_Temple"}, {"title": "Amritsar, A Sacred Destination & Wagah Border (FOM Singapore)", "url": "https://www.fom.sg/Upload/ckeditor/AMRITSAR%20copy.pdf"}], "summary_sd": "امرتسر پنجاب جو مقدس ترين شھر ۽ سک مذھب جو روحاني مرڪز آھي. ان کي چوٿين سک گرو رام داس ٻڌايو ۽ ھتي ئي ھرمندر صاحب يعني گولڊن ٽيمپل واقع آھي. 1919ع ۾ ھتي ئي جليانوالا باغ جو المناک قتل عام ٿيو.", "summary_ur": "امرتسر پنجاب کا مقدس ترین شہر اور سکھ مذہب کا روحانی مرکز ہے۔ اسے چوتھے سکھ گرو رام داس نے بسایا اور یہیں ہرمندر صاحب یعنی گولڈن ٹیمپل واقع ہے۔ 1919 میں یہیں جلیانوالہ باغ کا المناک قتل عام ہوا۔", "timeline": [{"era": "1577ء: قیام", "text_sd": "گرو رام داس امرت سروور کوٽايو؛ شھر جو بنياد.", "text_ur": "گرو رام داس نے امرت سروور کھدوایا؛ شہر کی بنیاد۔"}, {"era": "1588-1604ء", "text_sd": "گرو ارجن ديو ھرمندر صاحب ٺھرايو؛ آدي گرنٿ نصب ڪيو.", "text_ur": "گرو ارجن دیو نے ہرمندر صاحب بنوایا؛ آدی گرنتھ نصب کیا۔"}, {"era": "1809-1830ء", "text_sd": "رنجيت سنگھ تعمير نو ۽ سون جي تھ چاڙھي؛ گولڊن ٽيمپل.", "text_ur": "رنجیت سنگھ نے تعمیر نو اور سونے کی پرت چڑھوائی؛ گولڈن ٹیمپل۔"}, {"era": "13 اپریل 1919ء", "text_sd": "جليانوالا باغ قتل عام؛ جنرل ڊائر جي حڪم تي فائرنگ.", "text_ur": "جلیانوالہ باغ قتل عام؛ جنرل ڈائر کے حکم پر فائرنگ۔"}, {"era": "1947ء: تقسیم", "text_sd": "سرحدي شھر؛ فساد ۽ مھاجرن جي آمد.", "text_ur": "سرحدی شہر؛ فسادات اور مہاجرین کی آمد۔"}, {"era": "1984ء", "text_sd": "ھرمندر صاحب ڪمپليڪس ۾ فوجي آپريشن؛ پوءِ مرمت.", "text_ur": "ہرمندر صاحب کمپلیکس میں فوجی آپریشن؛ بعد میں مرمت۔"}]};
